const TRIGGER_RADIUS = 1;
const TARGET_NAME = 'Visual_1'; // 'Visual_2' for Trigger_2, 'Visual_3' for Trigger_3
const FADE_SPEED = 0.02;

let target;

function init() {
	target = scene.getObjectByName( TARGET_NAME );
	if ( target ) {
		target.material.transparent = true;
		target.material.opacity = 0;
	}
}

function update( event ) {
	if ( ! target ) return;
	const distance = camera.position.distanceTo( this.position );
	if ( distance <= TRIGGER_RADIUS ) {
		target.material.opacity = Math.min( 1, target.material.opacity + FADE_SPEED );
	}
}

