// Attach to Closing Trigger
const TRIGGER_RADIUS = 1;
const TARGET_NAMES = [ 'Visual_1', 'Visual_2', 'Visual_3', 'Visual_4' ]; // everything to fade out
const FADE_SPEED = 0.02;

let targets = [];

function init() {
	targets = TARGET_NAMES
		.map( name => scene.getObjectByName( name ) )
		.filter( obj => obj !== undefined );

	targets.forEach( obj => {
		obj.material.transparent = true;
	} );
}

function update( event ) {
	const distance = camera.position.distanceTo( this.position );
	if ( distance <= TRIGGER_RADIUS ) {
		targets.forEach( obj => {
			obj.material.opacity = Math.max( 0, obj.material.opacity - FADE_SPEED );
		} );
	}
}

