const SEAT_RADIUS = 1.5;
const SCREEN_POSITION = new THREE.Vector3( 5.482, 0.700, -1.577); // adjust to your screen's location
let promptEl, inRange = false;

function init() {
	promptEl = document.createElement( 'div' );
	Object.assign( promptEl.style, {
		position: 'fixed', bottom: '15%', left: '50%', transform: 'translateX(-50%)',
		background: 'rgba(0,0,0,0.75)', color: 'white', padding: '10px 18px',
		borderRadius: '6px', fontFamily: 'sans-serif', fontSize: '16px',
		display: 'none', zIndex: 1000
	} );
	document.body.appendChild( promptEl );

	window.cameraLocked = false;
	window.savedCameraPos = null;
	window.savedCameraRot = null;
}

function keydown( event ) {
	if ( event.code !== 'KeyE' ) return;

	if ( !window.cameraLocked && inRange ) {
		// Sit down: save current camera state, lock it facing the screen
		window.savedCameraPos = camera.position.clone();
		window.savedCameraRot = camera.rotation.clone();

		camera.position.copy( this.position );
		camera.lookAt( SCREEN_POSITION );

		window.cameraLocked = true;
		promptEl.textContent = "Press 'E' to stand up";
	} else if ( window.cameraLocked ) {
		// Stand up: restore previous camera position
		camera.position.copy( window.savedCameraPos );
		camera.rotation.copy( window.savedCameraRot );
		window.cameraLocked = false;
		promptEl.textContent = "Press 'E' to sit";
	}
}

function update( event ) {
	if ( window.cameraLocked ) return; // don't re-check distance while seated

	const distance = camera.position.distanceTo( this.position );
	inRange = distance <= SEAT_RADIUS;
	promptEl.style.display = inRange ? 'block' : 'none';
	if ( inRange ) promptEl.textContent = "Press 'E' to sit";
}

