let video, videoTexture, isPlaying = false, clickPromptEl;

function init() {
	video = document.createElement( 'video' );
	video.src = 'https://cdn.jsdelivr.net/gh/meershahmographer-bot/Test@main/Screen%20Recording%202026-06-11%20174434.mp4';
	video.crossOrigin = 'anonymous';
	video.loop = true;
	video.playsInline = true;
	videoTexture = new THREE.VideoTexture( video );
	videoTexture.colorSpace = THREE.SRGBColorSpace;

	clickPromptEl = document.createElement( 'div' );
	Object.assign( clickPromptEl.style, {
		position: 'fixed', bottom: '15%', left: '50%', transform: 'translateX(-50%)',
		background: 'rgba(0,0,0,0.75)', color: 'white', padding: '10px 18px',
		borderRadius: '6px', fontFamily: 'sans-serif', fontSize: '16px',
		display: 'none', zIndex: 1000
	} );
	document.body.appendChild( clickPromptEl );
}

function pointerdown( event ) {
	const raycaster = new THREE.Raycaster();
	const pointer = new THREE.Vector2();
	const rect = renderer.domElement.getBoundingClientRect();
	pointer.x = ( ( event.clientX - rect.left ) / rect.width ) * 2 - 1;
	pointer.y = -( ( event.clientY - rect.top ) / rect.height ) * 2 + 1;
	raycaster.setFromCamera( pointer, camera );
	const intersects = raycaster.intersectObject( this, true );
	if ( intersects.length === 0 ) return;

	if ( !isPlaying ) {
		this.material.map = videoTexture;
		this.material.needsUpdate = true;
		video.play();
		isPlaying = true;
	}
}

function update( event ) {
	// Only show "click to play" prompt while seated and looking at the screen, and not yet playing
	clickPromptEl.style.display = ( window.cameraLocked && !isPlaying ) ? 'block' : 'none';
	if ( clickPromptEl.style.display === 'block' ) {
		clickPromptEl.textContent = 'Click the screen to play';
	}
}

