// Set once, e.g. right after creating the camera
camera.rotation.order = 'YXZ';

// ============================
// MOVEMENT
// ============================
let moveForward = false;
let moveBackward = false;
let moveLeft = false;
let moveRight = false;
const speed = 0.03;

// ============================
// MOUSE ROTATION
// ============================
let mouseDown = false;
let previousMouseX = 0;
let previousMouseY = 0;
const mouseSensitivity = 0.005;

// ============================
// COLLISION
// ============================
const raycaster = new THREE.Raycaster();
const collisionBuffer = 0.5; // how close is "too close" to a wall

function getCollidables() {
    const objects = [];
    scene.traverse((obj) => {
        if (obj.userData && obj.userData.collidable) objects.push(obj);
    });
    return objects;
}

function canMove(direction, distance) {
    raycaster.set(camera.position, direction);
    const hits = raycaster.intersectObjects(getCollidables(), true);
    if (hits.length === 0) return true;
    return hits[0].distance > distance + collisionBuffer;
}

// ============================
// KEYBOARD
// ============================
function keydown(event) {
    if (event.code === 'KeyW') moveForward = true;
    if (event.code === 'KeyS') moveBackward = true;
    if (event.code === 'KeyA') moveLeft = true;
    if (event.code === 'KeyD') moveRight = true;
}
function keyup(event) {
    if (event.code === 'KeyW') moveForward = false;
    if (event.code === 'KeyS') moveBackward = false;
    if (event.code === 'KeyA') moveLeft = false;
    if (event.code === 'KeyD') moveRight = false;
}

// ============================
// MOUSE DOWN
// ============================
function pointerdown(event) {
    mouseDown = true;
    previousMouseX = event.clientX;
    previousMouseY = event.clientY;
}

// ============================
// MOUSE UP
// ============================
function pointerup(event) {
    mouseDown = false;
}

// ============================
// MOUSE MOVE
// ============================
function pointermove(event) {
    if (window.cameraLocked) return; // don't look around while seated
    if (!mouseDown) return;
    const movementX = event.clientX - previousMouseX;
    const movementY = event.clientY - previousMouseY;
    camera.rotation.y -= movementX * mouseSensitivity;
    camera.rotation.x -= movementY * mouseSensitivity;
    camera.rotation.x = Math.max(-Math.PI / 2, Math.min(Math.PI / 2, camera.rotation.x));
    previousMouseX = event.clientX;
    previousMouseY = event.clientY;
}

// ============================
// UPDATE
// ============================
const forward = new THREE.Vector3();
const right = new THREE.Vector3();

function update(event) {
    console.log( 'cameraLocked:', window.cameraLocked ); // temporary debug line
    if (window.cameraLocked) return; // don't move while seated

    forward.set(-Math.sin(camera.rotation.y), 0, -Math.cos(camera.rotation.y));
    right.set(-forward.z, 0, forward.x);
    if (moveForward && canMove(forward, speed)) {
        camera.position.addScaledVector(forward, speed);
    }
    if (moveBackward) {
        const back = forward.clone().negate();
        if (canMove(back, speed)) camera.position.addScaledVector(back, speed);
    }
    if (moveLeft) {
        const left = right.clone().negate();
        if (canMove(left, speed)) camera.position.addScaledVector(left, speed);
    }
    if (moveRight && canMove(right, speed)) {
        camera.position.addScaledVector(right, speed);
    }
}

