let panelImage, panelVideo, panelInfo;
let video, videoTexture;
let isOpen = false;

function init() {
	panelImage = scene.getObjectByName( 'PanelImage' );
	panelVideo = scene.getObjectByName( 'PanelVideo' );
	panelInfo = scene.getObjectByName( 'PanelInfo' );

	// Video setup
	video = document.createElement( 'video' );
	video.src = 'https://cdn.jsdelivr.net/gh/meershahmographer-bot/Test@main/Screen%20Recording%202026-06-11%20174434.mp4'; // replace with your actual video path
	video.crossOrigin = 'anonymous';
	video.loop = true;
	video.playsInline = true;
	videoTexture = new THREE.VideoTexture( video );
	videoTexture.colorSpace = THREE.SRGBColorSpace;

	if ( panelVideo ) {
		panelVideo.material.map = videoTexture;
		panelVideo.material.needsUpdate = true;
	}

	// Info panel: render text onto a canvas, use it as the texture
	const infoText = this.userData.info || 'No description set';
	const canvas = document.createElement( 'canvas' );
	canvas.width = 512;
	canvas.height = 512;
	const ctx = canvas.getContext( '2d' );
	ctx.fillStyle = '#1a1a1a';
	ctx.fillRect( 0, 0, canvas.width, canvas.height );
	ctx.fillStyle = '#ffffff';
	ctx.font = '28px sans-serif';
	wrapText( ctx, infoText, 20, 50, canvas.width - 40, 36 );

	const infoTexture = new THREE.CanvasTexture( canvas );
	if ( panelInfo ) {
		panelInfo.material.map = infoTexture;
		panelInfo.material.needsUpdate = true;
	}

	// Start hidden
	if ( panelImage ) panelImage.visible = false;
	if ( panelVideo ) panelVideo.visible = false;
	if ( panelInfo ) panelInfo.visible = false;
}

function wrapText( ctx, text, x, y, maxWidth, lineHeight ) {
	const words = text.split( ' ' );
	let line = '';
	for ( let n = 0; n < words.length; n++ ) {
		const testLine = line + words[ n ] + ' ';
		if ( ctx.measureText( testLine ).width > maxWidth && n > 0 ) {
			ctx.fillText( line, x, y );
			line = words[ n ] + ' ';
			y += lineHeight;
		} else {
			line = testLine;
		}
	}
	ctx.fillText( line, x, y );
}

function pointerdown( event ) {
	const raycaster = new THREE.Raycaster();
	const pointer = new THREE.Vector2();
	const rect = renderer.domElement.getBoundingClientRect();
	pointer.x = ( ( event.clientX - rect.left ) / rect.width ) * 2 - 1;
	pointer.y = -( ( event.clientY - rect.top ) / rect.height ) * 2 + 1;
	raycaster.setFromCamera( pointer, camera );
	const intersects = raycaster.intersectObject( this, true );
	if ( intersects.length === 0 ) return;

	isOpen = !isOpen;

	if ( panelImage ) panelImage.visible = isOpen;
	if ( panelVideo ) panelVideo.visible = isOpen;
	if ( panelInfo ) panelInfo.visible = isOpen;

	if ( isOpen ) {
		video.play();
	} else {
		video.pause();
	}
}

