const STATION_RADIUS = 1.5;
const WORDS = [
	{ name: 'Bismillah', imageUrl: 'YOUR_BISMILLAH_IMAGE_URL' },
	{ name: 'Salam', imageUrl: 'YOUR_SALAM_IMAGE_URL' },
	{ name: 'Amanah', imageUrl: 'YOUR_AMANAH_IMAGE_URL' }
];

let promptEl, overlayEl, canvasEl, ctx, exampleImg;
let inRange = false, isWriting = false, isDrawing = false;
let currentWordIndex = 0;
let lastX = 0, lastY = 0;

// Flat nib settings
const NIB_ANGLE = 45 * ( Math.PI / 180 ); // 45° is typical for Khat/Arabic calligraphy
const NIB_LENGTH = 10; // length of the flat nib edge (controls max stroke thickness)
const STROKE_COLOR = '#000';
const STROKE_OPACITY = 1; // constant, doesn't vary

function init() {
	window.cameraLocked = window.cameraLocked || false;

	// "Press E" prompt
	promptEl = document.createElement( 'div' );
	Object.assign( promptEl.style, {
		position: 'fixed', bottom: '15%', left: '50%', transform: 'translateX(-50%)',
		background: 'rgba(0,0,0,0.75)', color: 'white', padding: '10px 18px',
		borderRadius: '6px', fontFamily: 'sans-serif', fontSize: '16px',
		display: 'none', zIndex: 1000
	} );
	promptEl.textContent = "Press 'E' to write Khat";
	document.body.appendChild( promptEl );

	// Full overlay UI (shown only while locked)
	overlayEl = document.createElement( 'div' );
	Object.assign( overlayEl.style, {
		position: 'fixed', inset: '0', display: 'none',
		flexDirection: 'column', alignItems: 'center', justifyContent: 'center',
		zIndex: 999, fontFamily: 'sans-serif'
	} );

	overlayEl.innerHTML = `
		<div style="background:rgba(20,20,20,0.9); padding:24px; border-radius:12px; text-align:center;">
			<h2 id="wordTitle" style="color:white; margin:0 0 12px;">Trace: ${WORDS[0].name}</h2>
			<div style="position:relative; width:500px; height:250px; background:white; border-radius:8px; overflow:hidden; margin:0 auto;">
				<img id="exampleImg" src="${WORDS[0].imageUrl}" style="position:absolute; top:0; left:0; width:500px; height:250px; object-fit:contain; opacity:0.3; pointer-events:none;" />
				<canvas id="writeCanvas" width="500" height="250" style="position:absolute; top:0; left:0; width:500px; height:250px; cursor:crosshair;"></canvas>
			</div>
			<div style="margin-top:16px; display:flex; gap:10px; justify-content:center;">
				<button id="clearBtn" style="padding:8px 16px; border-radius:6px; border:none; cursor:pointer;">Clear</button>
				<button id="completeBtn" style="padding:8px 16px; border-radius:6px; border:none; cursor:pointer; background:#4caf50; color:white;">I'm Done</button>
			</div>
			<div id="resultArea" style="margin-top:16px; display:none;">
				<p style="color:#4caf50; font-size:18px;">🎉 Congratulations! 🎉</p>
				<div style="display:flex; gap:10px; justify-content:center;">
					<button id="nextWordBtn" style="padding:8px 16px; border-radius:6px; border:none; cursor:pointer;">Try Another Word</button>
					<button id="freeWriteBtn" style="padding:8px 16px; border-radius:6px; border:none; cursor:pointer;">Free Write</button>
				</div>
			</div>
			<p style="color:#aaa; margin-top:14px; font-size:13px;">Press 'E' to exit</p>
		</div>
	`;
	document.body.appendChild( overlayEl );

	canvasEl = overlayEl.querySelector( '#writeCanvas' );
	ctx = canvasEl.getContext( '2d' );
	exampleImg = overlayEl.querySelector( '#exampleImg' );

	// Flat-nib calligraphy brush
	canvasEl.addEventListener( 'mousedown', ( e ) => {
		isDrawing = true;
		const rect = canvasEl.getBoundingClientRect();
		lastX = e.clientX - rect.left;
		lastY = e.clientY - rect.top;
		stampNib( lastX, lastY );
	} );

	canvasEl.addEventListener( 'mousemove', ( e ) => {
		if ( !isDrawing ) return;
		const rect = canvasEl.getBoundingClientRect();
		const x = e.clientX - rect.left;
		const y = e.clientY - rect.top;

		const dx = x - lastX;
		const dy = y - lastY;
		const dist = Math.sqrt( dx * dx + dy * dy );
		const steps = Math.max( 1, Math.ceil( dist / 2 ) );

		for ( let i = 1; i <= steps; i++ ) {
			const ix = lastX + ( dx * i ) / steps;
			const iy = lastY + ( dy * i ) / steps;
			stampNib( ix, iy );
		}

		lastX = x;
		lastY = y;
	} );

	window.addEventListener( 'mouseup', () => { isDrawing = false; } );

	overlayEl.querySelector( '#clearBtn' ).addEventListener( 'click', () => {
		ctx.clearRect( 0, 0, canvasEl.width, canvasEl.height );
	} );

	overlayEl.querySelector( '#completeBtn' ).addEventListener( 'click', () => {
		overlayEl.querySelector( '#resultArea' ).style.display = 'block';
	} );

	overlayEl.querySelector( '#nextWordBtn' ).addEventListener( 'click', () => {
		currentWordIndex = ( currentWordIndex + 1 ) % WORDS.length;
		loadWord( currentWordIndex );
	} );

	overlayEl.querySelector( '#freeWriteBtn' ).addEventListener( 'click', () => {
		exampleImg.style.display = 'none';
		overlayEl.querySelector( '#wordTitle' ).textContent = 'Free Write';
		ctx.clearRect( 0, 0, canvasEl.width, canvasEl.height );
		overlayEl.querySelector( '#resultArea' ).style.display = 'none';
	} );

	// Direct document-level listener so E still works even after clicking a button
	document.addEventListener( 'keydown', handleExit );
}

function stampNib( x, y ) {
	ctx.save();
	ctx.globalAlpha = STROKE_OPACITY;
	ctx.fillStyle = STROKE_COLOR;
	ctx.translate( x, y );
	ctx.rotate( NIB_ANGLE );
	ctx.fillRect( -NIB_LENGTH / 2, -1, NIB_LENGTH, 2 );
	ctx.restore();
}

function loadWord( index ) {
	const word = WORDS[ index ];
	overlayEl.querySelector( '#wordTitle' ).textContent = 'Trace: ' + word.name;
	exampleImg.src = word.imageUrl;
	exampleImg.style.display = 'block';
	ctx.clearRect( 0, 0, canvasEl.width, canvasEl.height );
	overlayEl.querySelector( '#resultArea' ).style.display = 'none';
}

function handleExit( event ) {
	if ( event.code !== 'KeyE' ) return;

	if ( !window.cameraLocked && inRange ) {
		window.savedCameraPos = camera.position.clone();
		window.savedCameraRot = camera.rotation.clone();
		window.cameraLocked = true;
		isWriting = true;
		promptEl.style.display = 'none';
		overlayEl.style.display = 'flex';
	} else if ( isWriting ) {
		window.cameraLocked = false;
		camera.position.copy( window.savedCameraPos );
		camera.rotation.copy( window.savedCameraRot );
		isWriting = false;
		overlayEl.style.display = 'none';
	}
}

function update( event ) {
	if ( isWriting ) return;
	const distance = camera.position.distanceTo( this.position );
	inRange = distance <= STATION_RADIUS;
	promptEl.style.display = inRange ? 'block' : 'none';
}
